import {insightScenario} from '../../server/test/insight-helpers.js';
async function cliContext(scenario,fn){
  const created=(await scenario.api('POST','/tokens',{name:'Insight CLI',scopes:['*']})).data;
  const cli=args=>new Promise((resolve,reject)=>{
    const child=spawn(process.execPath,[fileURLToPath(new URL('../bin/crew.js',import.meta.url)),...args,'--url',scenario.server.url,'--token',created.token,'--json']);
    let stdout='',stderr='';const timer=setTimeout(()=>{child.kill('SIGKILL');reject(new Error('CLI test deadline'));},10000);
    child.stdout.on('data',chunk=>stdout+=chunk);child.stderr.on('data',chunk=>stderr+=chunk);
    child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);try{resolve({code,data:stdout&&!args.includes('--help')?JSON.parse(stdout):null,stdout,stderr});}catch(error){reject(error);}});
  });
  return fn(cli);
}
test('actual streamed export refuses overwrite and reports exact file bytes and hash',()=>insightScenario(s=>cliContext(s,async cli=>{
  const directory=await mkdtemp(tmpdir()+'/crew-transfer-cli-');
  try{
    const output=directory+'/project.json',result=await cli(['export',s.project.id,'--output',output]);assert.equal(result.code,0,result.stderr);
    const bytes=await readFile(output);assert.equal(result.data.bytes,bytes.length);assert.equal(result.data.sha256,createHash('sha256').update(bytes).digest('hex'));assert.equal(JSON.parse(bytes).issues[0].id,s.issue.id);
    assert.equal((await cli(['export',s.project.id,'--output',output])).code,1);assert.deepEqual(await readFile(output),bytes);
    const csv=await cli(['export',s.project.id,'--format','csv','--output',directory+'/project.csv']);assert.equal(csv.code,0,csv.stderr);assert.match(await readFile(directory+'/project.csv','utf8'),/"number","title"/);
  }finally{await rm(directory,{recursive:true,force:true});}
})));
test('actual streamed import preview writes nothing and confirmed import remaps a real project',()=>insightScenario(s=>cliContext(s,async cli=>{
  const directory=await mkdtemp(tmpdir()+'/crew-import-cli-');
  try{
    const output=directory+'/project.json';await cli(['export',s.project.id,'--output',output]);
    assert.equal((await cli(['import','--org',s.org.id,'--file',output,'--key','COPY'])).code,1);
    assert.equal((await cli(['import','--org',s.org.id,'--file',output,'--key','COPY','--preview=false','--yes=false'])).code,1);
    const preview=await cli(['import','--org',s.org.id,'--file',output,'--key','COPY','--preview']);assert.equal(preview.code,0,preview.stderr);assert.equal(preview.data.preview.counts.issues,1);
    assert.equal(s.server.ctx.db.prepare("SELECT count(*) n FROM projects WHERE key='COPY'").get().n,0);
    const imported=await cli(['import','--org',s.org.id,'--file',output,'--key','COPY','--yes']);assert.equal(imported.code,0,imported.stderr);assert.equal(imported.data.counts.issues,1);assert.notEqual(imported.data.mappings.issues[s.issue.id],s.issue.id);
  }finally{await rm(directory,{recursive:true,force:true});}
})));
test('actual dashboard CLI returns scoped real counts and all transfer families expose help',()=>insightScenario(s=>cliContext(s,async cli=>{
  const report=await cli(['dashboard','--org',s.org.id,'--project',s.project.id]);assert.equal(report.code,0,report.stderr);assert.equal(report.data.totals.issues,1);
  for(const group of ['dashboard','export','import'])assert.match((await cli([group,'--help'])).stdout,new RegExp('crew '+group));
})));

import test from 'node:test';
import assert from 'node:assert/strict';
import {setTimeout as delay} from 'node:timers/promises';
import {insightScenario} from './insight-helpers.js';
async function openStream(server,route,headers={}) {
  const controller=new AbortController();
  const timer=setTimeout(()=>controller.abort(new Error('SSE test deadline')),2500);
  const response=await fetch(server.url+'/api/v1/events'+route,{headers,signal:controller.signal});
  assert.equal(response.status,200);
  const reader=response.body.getReader(),decoder=new TextDecoder();
  let pending='';
  return {response,async next(){
    for(;;){
      const at=pending.indexOf('\n\n');
      if(at>=0){const frame=pending.slice(0,at);pending=pending.slice(at+2);const lines=frame.split('\n');return {event:lines.find(line=>line.startsWith('event: '))?.slice(7),data:JSON.parse(lines.find(line=>line.startsWith('data: ')).slice(6))};}
      const chunk=await reader.read();if(chunk.done)return null;pending+=decoder.decode(chunk.value,{stream:true});
    }
  },close(){clearTimeout(timer);controller.abort();reader.cancel().catch(()=>{});}};
}
test('real SSE emits sanitized visible activity and releases subscription after disconnect',()=>insightScenario(async({server,api,member,org,issue,cookie})=>{
  const baseline=server.ctx.bus.listenerCount;
  const stream=await openStream(server,'?orgId='+org.id,{cookie});
  try{
    assert.equal((await stream.next()).event,'ready');assert.equal(server.ctx.bus.listenerCount,baseline+1);
    await member('PATCH','/issues/'+issue.id,{title:'Live title'});
    const update=await stream.next();assert.equal(update.event,'activity');assert.equal(update.data.after.title,'Live title');assert.equal(update.data.entityId,issue.id);
  }finally{stream.close();}
  for(let attempt=0;attempt<20&&server.ctx.bus.listenerCount!==baseline;attempt++)await delay(5);
  assert.equal(server.ctx.bus.listenerCount,baseline);
}));
test('SSE rejects anonymous and insufficient scope credentials before streaming',()=>insightScenario(async({server,api,org})=>{
  const anonymous=await fetch(server.url+'/api/v1/events?orgId='+org.id);assert.equal(anonymous.status,401);
  const token=(await api('POST','/tokens',{name:'No insight',scopes:['self:read']})).data.token;
  const denied=await fetch(server.url+'/api/v1/events?orgId='+org.id,{headers:{Authorization:'Bearer '+token}});assert.equal(denied.status,403);
}));
test('SSE closes immediately when its browser session is revoked',()=>insightScenario(async({server,api,org,cookie})=>{
  const sessions=(await api('GET','/auth/sessions')).data.items,current=sessions.find(session=>session.current);
  const stream=await openStream(server,'?orgId='+org.id,{cookie});
