  let state=emptyPicker(first);state=pickerAction(state,{type:'draft',value:'late'});state=pickerAction(state,{type:'search'});state=pickerAction(state,{type:'next',cursor:'next'});
  assert.equal(scopedPicker(state,first),state);assert.deepEqual(scopedPicker(state,other),emptyPicker(other));
});
test('selected entity labels remain available outside the current search page',()=>{assert.deepEqual(selectedOption([{id:'first'}],'later',{items:[{id:'later',label:'Visible later item'}]}),{id:'later',label:'Visible later item'});assert.equal(selectedOption([],'revoked',{items:[]}),null);});
test('new file or organization invalidates delayed preview without authorizing another draft',async()=>{
  const guard=createRequestGuard(),old=guard.begin(),applied=[];let resolve;
  const delayed=new Promise(done=>resolve=done).then(value=>guardedResult(guard,old,item=>applied.push(item),value));
  guard.invalidate();const current=guard.begin();resolve({project:'old'});assert.equal(await delayed,false);assert.deepEqual(applied,[]);
  assert.equal(guardedResult(guard,current,item=>applied.push(item),{project:'new'}),true);assert.deepEqual(applied,[{project:'new'}]);
});
test('new action and component disposal suppress earlier digest watch and import responses',()=>{
  const guard=createRequestGuard(),old=guard.begin(),latest=guard.begin();assert(old.signal.aborted);assert.equal(guard.current(old),false);assert.equal(guard.current(latest),true);guard.invalidate();assert(latest.signal.aborted);assert.equal(guardedResult(guard,latest,()=>{throw new Error('must not run');},{}),false);
});
