  const document={statuses:[{id:'s',name:'Doing'}],users:[{id:'u',name:'Alex',email:'a@example.test'}],labels:[{id:'l',name:'Release'}],issues:[{id:'i',number:2,title:'Child',statusId:'s',assigneeId:'u',parentId:'p',labelIds:['l']},{id:'p',number:1,title:'Parent',labelIds:[]}],comments:[],relations:[]};
